def chain_chain_follows(chain):
    chain_list = list(chain)
    chain_dict = {}
    for i, token in enumerate(chain_list):
        if token not in chain_dict:
            chain_dict[token] = i

    current = chain_list[0]
    result = []

    while chain_dict:
        next_token = chain_dict[current]
        result.append(current)
        current = chain_list[next_token]
        chain_dict.pop(current)

    return ','.join(result)

# Example usage:
